import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{o as a,c as t,a8 as s}from"./chunks/vendor-scheduler.BuXoCeGx.js";const E=JSON.parse('{"title":"筛选面板收口指南","description":"面向后台项目的筛选条与输入浮层收口入口索引，优先减少页面级 deep 覆盖。","frontmatter":{"title":"筛选面板收口指南","description":"面向后台项目的筛选条与输入浮层收口入口索引，优先减少页面级 deep 覆盖。","outline":"deep"},"headers":[],"relativePath":"guide/filter-surface-migration.md","filePath":"guide/filter-surface-migration.md","lastUpdated":1779528939000}'),l={name:"guide/filter-surface-migration.md"};function p(d,e,o,r,n,h){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="筛选面板收口指南" tabindex="-1">筛选面板收口指南 <a class="header-anchor" href="#筛选面板收口指南" aria-label="Permalink to &quot;筛选面板收口指南&quot;">​</a></h1><p>这页只解决一类问题：后台项目里最常见的筛选条、搜索条和输入浮层，应该优先怎么收口，避免继续在页面层 deep 到内部类名。</p><p>如果你还没看过总迁移策略，先读 <a href="/guide/backend-migration">后台迁移指南</a>。如果你已经知道自己主要在处理筛选条，这页可以直接当操作索引用。</p><h2 id="先判断这是不是组件库层问题" tabindex="-1">先判断这是不是组件库层问题 <a class="header-anchor" href="#先判断这是不是组件库层问题" aria-label="Permalink to &quot;先判断这是不是组件库层问题&quot;">​</a></h2><p>下面这些现象，默认都先判断为“组件库公开入口没被正确使用”或“历史页面覆盖还没回收”，而不是先去业务页继续补样式：</p><ul><li>下拉面板、日期面板、时间面板、树筛选面板看起来不像一套主题。</li><li>业务页里还在大量写 <code>:deep(.xy-*-dropdown)</code>、<code>__option</code>、<code>__cell</code>、<code>__search</code>、<code>__trigger</code> 这类类名。</li><li>主题切换后，筛选区只有个别组件还保留旧亮底、旧阴影、旧边框。</li><li>页面只是想让筛选条更克制一点，却在每个组件上单独调 trigger、option、shortcut、search item。</li></ul><p>一句话判断：</p><ul><li>如果你改的是“背景、边框、阴影、圆角、hover、selected、快捷项、搜索区、列区层次”，先回到组件库实例级入口。</li><li>如果你改的是“页面布局、业务字段排列、动作区位置、表单协议”，那才更可能属于业务页。</li></ul><h2 id="推荐收口顺序" tabindex="-1">推荐收口顺序 <a class="header-anchor" href="#推荐收口顺序" aria-label="Permalink to &quot;推荐收口顺序&quot;">​</a></h2><ol><li>先删页面层对面板本体的覆盖： <ul><li><code>dropdown / panel / popper / search / option / cell / shortcut / column</code></li></ul></li><li>再看组件库默认基线是否已满足页面。</li><li>仍需微调时，只在实例级入口或页面 wrapper 上接 token。</li><li>最后才考虑是否真的需要业务局部样式。</li></ol><p>不建议的顺序是：</p><ol><li>保留旧 deep 覆盖</li><li>再叠一层 <code>popper-class</code></li><li>最后分不清到底哪一层在生效</li></ol><h2 id="统一收口入口" tabindex="-1">统一收口入口 <a class="header-anchor" href="#统一收口入口" aria-label="Permalink to &quot;统一收口入口&quot;">​</a></h2><p>筛选链路里最常用的组件，当前推荐入口如下：</p><div class="xy-vp-table"><table><thead><tr><th>组件</th><th>优先入口</th><th>不建议继续 deep 的位置</th></tr></thead><tbody><tr><td><code>select</code></td><td><code>popper-class</code>、<code>popper-style</code>、<code>dropdown-min-width / dropdown-max-width</code></td><td><code>__dropdown / __option / __group</code></td></tr><tr><td><code>auto-complete</code></td><td><code>popper-class</code>、<code>popper-style</code>、<code>dropdown-min-width / dropdown-max-width</code></td><td><code>__option / __loading / __empty</code></td></tr><tr><td><code>date-picker</code></td><td>面板实例级变量、wrapper token</td><td><code>__panel / __shortcut / __cell / __header</code></td></tr><tr><td><code>time-picker</code></td><td>面板实例级变量、wrapper token</td><td><code>__panel / __column / __action</code></td></tr><tr><td><code>time-select</code></td><td>组件实例级入口、wrapper token</td><td><code>__dropdown / __option / __trigger</code></td></tr><tr><td><code>tree-select</code></td><td><code>popper-class</code>、<code>popper-style</code></td><td><code>__dropdown / __tree / __search</code></td></tr><tr><td><code>cascader</code></td><td><code>popper-class</code>、<code>popper-style</code></td><td><code>__dropdown / __columns / __option / __search-results</code></td></tr></tbody></table></div><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><p>如果你是从业务项目回过来收口后台筛选区，建议按下面顺序读：</p><ol><li><a href="/guide/backend-migration">后台迁移指南</a></li><li><a href="/components/select">Select 选择器</a></li><li><a href="/components/date-picker">DatePicker 日期选择器</a></li><li><a href="/components/time-picker">TimePicker 时间选择器</a></li><li><a href="/components/time-select">TimeSelect 时间选择</a></li><li><a href="/components/auto-complete">AutoComplete 自动完成</a></li><li><a href="/components/tree-select">TreeSelect 树选择</a></li><li><a href="/components/cascader">Cascader 级联选择</a></li></ol><p>如果你主要是在收轻交互浮层，而不是值选择，也一并看：</p><ul><li><a href="/components/tooltip">Tooltip 文字提示</a></li><li><a href="/components/popover">Popover 气泡卡片</a></li><li><a href="/components/dropdown">Dropdown 下拉菜单</a></li></ul><h2 id="可直接抄的示例入口" tabindex="-1">可直接抄的示例入口 <a class="header-anchor" href="#可直接抄的示例入口" aria-label="Permalink to &quot;可直接抄的示例入口&quot;">​</a></h2><p>这批组件已经有“实例级样式收口”示例，可以直接对照改：</p><div class="xy-vp-table"><table><thead><tr><th>场景</th><th>示例</th></tr></thead><tbody><tr><td>通用提示浮层</td><td><a href="/components/tooltip#实例级样式收口">tooltip/popper-class</a></td></tr><tr><td>单选下拉</td><td><a href="/components/select#实例级样式收口">select/popper-class</a></td></tr><tr><td>日期面板</td><td><a href="/components/date-picker#实例级样式收口">date-picker/popper-class</a></td></tr><tr><td>联想输入</td><td><a href="/components/auto-complete#实例级样式收口">auto-complete/popper-class</a></td></tr><tr><td>树筛选</td><td><a href="/components/tree-select#实例级样式收口">tree-select/popper-class</a></td></tr><tr><td>级联选择</td><td><a href="/components/cascader#实例级样式收口">cascader/popper-class</a></td></tr><tr><td>轻交互卡片</td><td><a href="/components/popover#实例级样式收口">popover/popper-class</a></td></tr><tr><td>操作菜单</td><td><a href="/components/dropdown#实例级样式收口">dropdown/popper-class</a></td></tr></tbody></table></div><h2 id="页面-wrapper-的使用边界" tabindex="-1">页面 wrapper 的使用边界 <a class="header-anchor" href="#页面-wrapper-的使用边界" aria-label="Permalink to &quot;页面 wrapper 的使用边界&quot;">​</a></h2><p>如果页面只是做主题接轨，优先在筛选条外层 wrapper 上接少量全局 token，而不是继续 deep 单个组件内部类名。</p><p>示例：</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;filter-shell&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xy-select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xy-date-picker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xy-time-select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xy-tree-select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scoped</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.filter-shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  --xy-bg-color-elevated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--bg-elevated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  --xy-border-color-strong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--border-strong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>这个 wrapper 适合做：</p><ul><li>页面主题接轨</li><li>少量全局亮暗色过渡</li><li>多个筛选组件共享的边框强度和背景层次</li></ul><p>这个 wrapper 不适合做：</p><ul><li>继续 deep 到 <code>__dropdown / __option / __cell / __search</code></li><li>为单个组件写一整套结构样式</li><li>把本该由组件实例级变量解决的问题重新拉回页面层</li></ul><h2 id="常见误用" tabindex="-1">常见误用 <a class="header-anchor" href="#常见误用" aria-label="Permalink to &quot;常见误用&quot;">​</a></h2><h3 id="用-dropdown-代替值选择器" tabindex="-1">用 <code>dropdown</code> 代替值选择器 <a class="header-anchor" href="#用-dropdown-代替值选择器" aria-label="Permalink to &quot;用 \`dropdown\` 代替值选择器&quot;">​</a></h3><p>如果你处理的是“状态筛选、枚举值选择、层级选择”，优先回到：</p><ul><li><code>select</code></li><li><code>tree-select</code></li><li><code>cascader</code></li></ul><p>不要因为 <code>dropdown</code> 容易写，就在页面层拿它代替值选择器，再额外补大量样式。</p><h3 id="把时间和日期面板拆成很多局部补丁" tabindex="-1">把时间和日期面板拆成很多局部补丁 <a class="header-anchor" href="#把时间和日期面板拆成很多局部补丁" aria-label="Permalink to &quot;把时间和日期面板拆成很多局部补丁&quot;">​</a></h3><p>如果问题只是“时间/日期面板比其他下拉更重、更亮、不像一套”，优先统一面板变量和 wrapper token，不要分别修：</p><ul><li>日期格</li><li>快捷项</li><li>时间列</li><li>操作区</li></ul><h3 id="先写-popper-class-但旧-deep-覆盖没删" tabindex="-1">先写 <code>popper-class</code>，但旧 deep 覆盖没删 <a class="header-anchor" href="#先写-popper-class-但旧-deep-覆盖没删" aria-label="Permalink to &quot;先写 \`popper-class\`，但旧 deep 覆盖没删&quot;">​</a></h3><p>这是最常见的伪收口。正确顺序是：</p><ol><li>先删旧 deep 覆盖</li><li>再观察组件库默认态</li><li>最后补实例级入口</li></ol><h2 id="联调时怎么判断算收口成功" tabindex="-1">联调时怎么判断算收口成功 <a class="header-anchor" href="#联调时怎么判断算收口成功" aria-label="Permalink to &quot;联调时怎么判断算收口成功&quot;">​</a></h2><p>满足下面几点，通常就说明这批筛选区已经基本回到组件库层：</p><ul><li>主题切换后，输入浮层看起来属于同一套背景、边框和阴影体系。</li><li>业务页不再依赖大量 <code>:deep(.xy-*)</code> 去修 option、cell、search、shortcut。</li><li>页面仍保留少量 wrapper token，但不再反向绑定内部 DOM 结构。</li><li>需要微调时，优先能在组件实例或示例里找到对应入口，而不是重新开一层页面补丁。</li></ul><h2 id="这次后台联调里已经验证的模式" tabindex="-1">这次后台联调里已经验证的模式 <a class="header-anchor" href="#这次后台联调里已经验证的模式" aria-label="Permalink to &quot;这次后台联调里已经验证的模式&quot;">​</a></h2><p>这次对后台项目做只读审计后，筛选链路里已经能确认两类模式：</p><h3 id="可以保留" tabindex="-1">可以保留 <a class="header-anchor" href="#可以保留" aria-label="Permalink to &quot;可以保留&quot;">​</a></h3><ul><li>页面 wrapper 上的 token 接轨</li><li>组件实例上的 <code>popper-class</code></li><li>业务自定义 <code>body-class</code> 或自定义 class，再配合 scoped 样式命中这个业务类名</li></ul><h3 id="下一批仍应继续收口" tabindex="-1">下一批仍应继续收口 <a class="header-anchor" href="#下一批仍应继续收口" aria-label="Permalink to &quot;下一批仍应继续收口&quot;">​</a></h3><ul><li>全局 <code>.xy-dialog</code> 根类覆盖带出来的统一弹窗尺寸和圆角规则</li><li>全局 <code>.xy-table</code> 根类覆盖带出来的移动端滚动/布局规则</li><li>任何继续命中 <code>__dropdown / __option / __search / __cell / __column</code> 的旧式页面级覆盖</li></ul><p>所以这轮之后的迁移重点已经很明确：</p><ul><li>不要再把 wrapper token 当成“旧补丁”</li><li>真正该继续收的是“全局根类直改组件表现”和“内部结构类名覆盖”</li></ul>`,53)])])}const u=i(l,[["render",p]]);export{E as __pageData,u as default};
